  function buildGoldenRoute(parent, branch, accent, chosen = true, all = false) {
    const group = new Group();
    group.name = "goldenRoute";
    mats.routeCasing = mats.routeCasing || new MeshStandardMaterial({ color: "#2a2620", roughness: 0.9 });
    mats.route = mats.route || new MeshStandardMaterial({ color: accent, roughness: 0.65 });
    mats.routeDash = mats.routeDash || new MeshBasicMaterial({ color: "#fffdf2" });
    mats.routeAlt = mats.routeAlt || new MeshStandardMaterial({ color: "#c9c5b8", roughness: 1 });
    for (const b2 of BRANCHES) {
      if ((b2 === branch && chosen) || all) continue;
      group.add(roadRibbonFromMap(roundedPolyline(branchRoute(b2)), chosen ? ROUTE_W * 0.8 : ROUTE_W, b2 === branch ? 0.72 : 0.7, mats.routeAlt));
    }
    const flat = branchPoints(branch);
    const dense = roundedPolyline(flat).filter(([, z]) => z <= RAMP_LIP + 1);
    const all3 = dense.map(([x, z, y]) => new Vector3(x, z > RAMP_BASE - 1 ? elevationAt(z) : y, z));
    // before the choice only the shared road is gold: up to the fork, and from the merge on
    const [fI, jI] = branchSpan(dense);
    const runs = [];
    if (chosen) runs.push(all3);
    else {
      if (fI > 1) runs.push(all3.slice(0, fI + 1));
      if (jI < all3.length - 2) runs.push(all3.slice(jI));
    }
    for (const p3 of runs) addGold(p3);
    // r101: on the map every street is open: all three are gold, no choosing
    if (all) for (const b2 of BRANCHES) {
      if (b2 === branch && chosen) continue;
      const d2 = roundedPolyline(branchPoints(b2)).filter(([, z]) => z <= RAMP_LIP + 1);
      const p2 = d2.map(([x, z, y]) => new Vector3(x, z > RAMP_BASE - 1 ? elevationAt(z) : y, z));
      const [f2, j2] = branchSpan(d2);
      addGold(p2.slice(Math.max(0, f2 - 1), j2 + 2));
    }
    parent.add(group);
    return group;
    function addGold(p3) {
    const casing = new Mesh(ribbonGeometry(p3, ROUTE_W + 4.5, 0.8), mats.routeCasing);
    const body = new Mesh(ribbonGeometry(p3, ROUTE_W, 1.3), mats.route);
    casing.receiveShadow = body.receiveShadow = true;
    group.add(casing, body);
    const dashGeo = new PlaneGeometry(3.6, 20);
    dashGeo.rotateX(-Math.PI / 2);
    let total = 0;
    const lens = [0];
    for (let i = 1; i < p3.length; i++) {
      total += p3[i].distanceTo(p3[i - 1]);
      lens.push(total);
    }
    const step = 88;
    const nD = Math.floor(total / step);
    const dashes = new InstancedMesh(dashGeo, mats.routeDash, nD);
    const m = new Matrix4();
    const q = new Quaternion();
    const up = new Vector3(0, 1, 0);
    let li = 0;
    for (let i = 0; i < nD; i++) {
      const L = i * step + step / 2;
      while (li < lens.length - 2 && lens[li + 1] < L) li++;
      const f = (L - lens[li]) / (lens[li + 1] - lens[li] || 1);
      const p = new Vector3().lerpVectors(p3[li], p3[li + 1], f);
      const dir = new Vector3().subVectors(p3[li + 1], p3[li]);
      dir.y = 0;
      dir.normalize();
      q.setFromUnitVectors(new Vector3(0, 0, 1), dir);
      m.compose(new Vector3(p.x, p.y + 1.8, p.z), q, new Vector3(1, 1, 1));
      dashes.setMatrixAt(i, m);
    }
    group.add(dashes);
    }
  }
