    const seat = new Mesh(new BoxGeometry(26, 1.4, 5.5), benchM); seat.position.set(-17, 5.2, D / 2 + 5.5);
    for (const lx of [-28, -6]) { const leg = new Mesh(new BoxGeometry(1.4, 4.6, 4.6), benchM); leg.position.set(lx, 2.3, D / 2 + 5.5); g.add(leg); }
