  var steamCaseHtml = "<!DOCTYPE html>\n<html lang=\"en\"><!-- lang=\"ro\" for the Romanian version -->\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<!-- <meta name=\"robots\" content=\"noindex, nofollow\"> uncomment for preview copies uploaded to the site -->\n<title>Steam \u2014 Cromatic Studios</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Darker+Grotesque:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --ink:#121212;\n  --paper:#F1F1F1;\n  --white:#FFFFFF;\n  --yellow:#FFD147;\n  --cream:#FFEDB5;\n  --blue:#519EF5;\n  --blue-soft:#DCEBFD;\n  --green:#2ECB42;\n  --green-soft:#D8F5DC;\n  --purple:#B49BE0;\n  --purple-soft:#EAE2F8;\n  --red:#F0544C;\n  --red-soft:#FCDEDC;\n  --orange:#F58D42;\n  --orange-soft:#FCE3CF;\n  --muted:#5a5a5a;\n\n  --radius-l:36px;\n  --radius-m:18px;\n  --line:2px solid var(--ink);\n  --gutter:clamp(10px,1.2vw,16px);\n  --pad:clamp(22px,4vw,64px);\n  --media-pad:var(--gutter);\n  --font:\"Darker Grotesque\",system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif;\n\n  /* type scale (~1.333), 375px -> 1440px */\n  --fs-display:clamp(3rem,1.591rem + 6.01vw,7rem);\n  --fs-hero:clamp(2.86rem,1.761rem + 4.687vw,5.98rem);\n  --fs-h2:clamp(2.5rem,1.708rem + 3.38vw,4.75rem);\n  --fs-h3:clamp(1.875rem,1.479rem + 1.69vw,3rem);\n  --fs-lead:clamp(1.375rem,1.199rem + .751vw,1.875rem);\n  --fs-body:clamp(1.125rem,1.059rem + .282vw,1.3125rem);\n  --fs-ui:clamp(1.0625rem,1.041rem + .094vw,1.125rem);\n  --fs-small:clamp(.9375rem,.916rem + .094vw,1rem);\n  /* line heights: standard values reduced by 15% */\n  --lh-display:.89;\n  --lh-hero:.9;\n  --lh-h2:.92;\n  --lh-h3:.95;\n  --lh-lead:1.1;\n  --lh-body:1.2;\n  --lh-ui:1.1;\n  --lh-small:1.15;\n  --rail-h:clamp(300px,34vw,520px);\n  --caption-gap:8px;\n  --max-h:min(78svh,760px);\n}\n*,*::before,*::after{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{margin:0;background:var(--paper);color:var(--ink);font-family:var(--font);font-size:var(--fs-body);font-weight:600;line-height:var(--lh-body);-webkit-font-smoothing:antialiased}\nimg,video,iframe{display:block;max-width:100%}\na{color:inherit}\nh1,h2,h3,p,figure,ul,blockquote{margin:0}\nh1,h2,h3{font-weight:900;letter-spacing:-.01em}\n:focus-visible{outline:3px solid var(--blue);outline-offset:3px;border-radius:6px}\n.page{padding:var(--gutter);display:grid;grid-template-columns:minmax(0,1fr);gap:var(--gutter)}\n.card{min-width:0;border:var(--line);border-radius:var(--radius-l);overflow:hidden}\n.inner{padding:var(--pad)}\n.prose{max-width:34em}\n.prose p+p{margin-top:.8em}\n.prose strong{font-weight:900}\n\n/* pills */\n.pills{display:flex;flex-wrap:wrap;gap:8px;list-style:none;padding:0}\n.pill{display:inline-block;padding:6px 20px 8px;border:var(--line);border-radius:999px;font-weight:700;font-size:var(--fs-ui);line-height:var(--lh-ui);text-decoration:none;transition:background .2s}\n.pill--brand{background:var(--green)}\n.pill--marketing{background:var(--red)}\n.pill--product{background:var(--purple)}\n.pill--accent{background:var(--yellow)}\n.pill--video{background:var(--orange)}\na.pill:hover{background:var(--white)}\n\n/* media: every frame keeps the file's own ratio (--r) */\n.frame{position:relative;width:100%;aspect-ratio:var(--r,1.5);max-height:var(--max-h);border-radius:var(--radius-m);overflow:hidden;background:#d9d9d9}\n.frame img,.frame video{width:100%;height:100%;object-fit:cover}\nfigcaption{margin-top:var(--caption-gap);font-size:var(--fs-small);font-weight:600;color:var(--muted);line-height:var(--lh-small)}\n.stack{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--gutter)}\n.stack>figcaption{margin-top:calc(var(--caption-gap) - var(--gutter))}\n.chapter-media>figcaption{margin-top:calc(var(--caption-gap) - clamp(28px,3vw,48px))}\n/* justified rows: widths follow each ratio, so heights match with zero cropping */\n.row{display:flex;flex-wrap:wrap;gap:var(--gutter)}\n.row>figure{flex:var(--r) 1 0;min-width:0}\n\n/* carousels: fixed height, width from ratio */\n.rail-head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:12px}\n.rail-head h4{margin:0;display:flex;flex-wrap:wrap;gap:0;padding-top:5%}\n.rail-head h4 .pill{background:var(--white);font-size:var(--fs-ui);line-height:var(--lh-ui);font-weight:800;position:relative;transform:rotate(var(--rot,-9deg))}\n.rail-head h4 .pill:nth-child(even){margin-left:-14px;z-index:1;transform:rotate(var(--rot,7deg))}\n@media (min-width:1025px){\n  .chapter-media>:first-child .rail-head h4,.chapter-media>.rail-head:first-child h4{padding-top:2%}\n}\n.rail-btns{display:flex;gap:6px}\n.rail-btns button{width:46px;height:46px;border-radius:50%;border:var(--line);background:var(--white);font:inherit;font-size:calc(var(--fs-ui) * 1.63);line-height:1;cursor:pointer;display:grid;place-items:center;padding:0 0 2px}\n.rail-btns button:hover{background:var(--yellow)}\n.rail-btns button:disabled{opacity:.3;cursor:default;background:var(--white)}\n.track{display:flex;gap:var(--gutter);overflow-x:auto;scroll-behavior:auto;scroll-snap-type:x proximity;scrollbar-width:none;overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch}\n.track::-webkit-scrollbar{display:none}\n.track>*{flex:0 0 auto;scroll-snap-align:start}\n.track>figure{width:calc(var(--rail-h) * var(--r))}\n.track>figure .frame{width:100%;height:var(--rail-h);max-height:none}\n.track img{-webkit-user-drag:none;user-select:none}\n.track.is-dragging{scroll-snap-type:none;cursor:grabbing;user-select:none}\n.track.is-dragging *{pointer-events:none}\n@media (hover:hover) and (pointer:fine){.track{cursor:grab}}\n\n/* hero */\n.hero{background:var(--white)}\n.hero-top{display:grid;grid-template-columns:minmax(0,2.2fr) minmax(300px,1fr);gap:clamp(24px,4vw,72px);align-items:start}\n.hero h1{font-size:var(--fs-hero);line-height:var(--lh-hero)}\n.hero-info{display:grid;gap:clamp(18px,2vw,28px);padding-top:15px}\n.hero-title{display:grid;gap:clamp(10px,1vw,16px)}\n.client-row{display:flex;flex-wrap:wrap;align-items:center;gap:12px 18px}\n.client-row .pill{font-weight:800;opacity:0;animation:pill-drop .95s cubic-bezier(.45,0,.9,.5) both}\n.client-row li:nth-child(1) .pill{animation-delay:1.1s}\n.client-row li:nth-child(2) .pill{animation-delay:1.28s}\n.client-row li:nth-child(3) .pill{animation-delay:1.46s}\n@keyframes pill-drop{\n  0%{opacity:0;transform:translateY(-190px)}\n  10%{opacity:1}\n  52%{transform:translateY(0);animation-timing-function:cubic-bezier(.2,.6,.4,1)}\n  70%{transform:translateY(-22px);animation-timing-function:cubic-bezier(.5,0,.9,.5)}\n  85%{transform:translateY(0);animation-timing-function:cubic-bezier(.2,.6,.4,1)}\n  93%{transform:translateY(-7px)}\n  100%{opacity:1;transform:translateY(0)}\n}\n.client-name{font-size:var(--fs-lead);font-weight:900;line-height:var(--lh-lead)}\n.info{list-style:none;padding:0;display:grid;gap:14px}\n.info li:first-child{font-weight:800}\n.hero-media{margin-top:clamp(28px,4vw,56px);animation:hero-in .85s ease-in .2s both}\n@keyframes hero-in{0%{opacity:0;transform:scale(.5)}28%{opacity:1;transform:scale(.5)}100%{opacity:1;transform:scale(1)}}\n.hero-media .frame{border:var(--line);border-radius:24px}\n\n/* section heads */\n.sec-head>.prose{padding-top:15px}\n.sec-head{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,72px);align-items:start}\n.sec-head h2{font-size:var(--fs-h2);line-height:var(--lh-h2)}\n\n/* problem */\n.problem{background:var(--white)}\n.problem-media{margin-top:clamp(32px,5vw,72px)}\n.quote{margin-top:clamp(32px,5vw,72px);padding:6.53% 19%;display:block}\n.quote blockquote p{font-size:var(--fs-h3);font-weight:800;line-height:var(--lh-h3);color:var(--blue)}\n.quote cite,.result-quote cite{display:block;margin-top:16px;font-size:var(--fs-small);line-height:var(--lh-small);font-weight:800;color:var(--ink);font-style:normal;opacity:0;transition:opacity .7s ease .1s}\n.line{display:block;overflow:hidden;padding-bottom:.22em;margin-bottom:-.22em}\n.line>span{display:block;transform:translateY(110%);opacity:0}\n.is-in .line>span{transform:none;opacity:1;transition:transform var(--line-dur,.85s) cubic-bezier(.2,.75,.2,1),opacity var(--line-dur,.85s) ease;transition-delay:calc(var(--i) * var(--line-step,.09s))}\n.is-in cite{opacity:1;transition-delay:calc(var(--lines,1) * var(--line-step,.09s) + .35s)}\n\n.handoff{margin-top:clamp(40px,6vw,96px);display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:var(--gutter)}\n.solution-intro{background:var(--blue);border:var(--line);border-radius:var(--radius-m);padding:clamp(24px,3.5vw,56px);display:grid;gap:clamp(18px,2vw,28px);align-content:start}\n.solution-intro h2{font-size:var(--fs-h2);line-height:var(--lh-h2)}\n.solution-intro p{max-width:none}\n.to-result{display:flex;flex-direction:column;justify-content:flex-end;gap:6px;padding:clamp(24px,3vw,40px);background:var(--ink);color:var(--white);border-radius:var(--radius-m);text-decoration:none;transition:transform .2s}\n.to-result b{font-size:calc(var(--fs-lead) * 1.1);font-weight:900;line-height:var(--lh-lead);color:var(--yellow)}\n.go-icon{font-size:1.63em;line-height:1;display:block;transform:translateY(-.02em)}\n.to-result-go{align-self:flex-start;display:inline-flex;align-items:center;gap:10px;margin-top:24px;padding:11px 24px 12px;border-radius:999px;border:1px solid var(--yellow);background:var(--yellow);color:var(--ink);font-weight:800;font-size:var(--fs-ui);line-height:var(--lh-ui)}\n.to-result:hover .to-result-go{background:var(--white);border-color:var(--white)}\n.to-result .to-result-go:hover,.to-result:hover .to-result-go:hover{background:var(--green);border-color:var(--green)}\n.to-result:hover{transform:translateY(-3px)}\n\n/* chapters */\n.chapter{background:var(--white);display:grid;grid-template-columns:minmax(200px,3.2fr) minmax(0,8.8fr)}\n.chapter-side{padding:clamp(22px,2.6vw,44px);border-right:var(--line)}\n.chapter-side>div{display:grid;gap:clamp(18px,2vw,28px)}\n.pill-title{display:flex;flex-direction:column;align-items:flex-start}\n.pill-title{padding-block:6px}\n.pill-title .pill{font-size:var(--fs-lead);line-height:var(--lh-lead);font-weight:900;-webkit-text-stroke:.7px var(--ink);padding:10px 22px 13px;position:relative;transform:rotate(-2.5deg);transform-origin:left center}\n.pill-title .pill:last-child{margin-left:16px;margin-top:-6px;z-index:1;transform:rotate(1.5deg)}\n/* the two title pills drop into place when the chapter first appears */\n.pill-title.drop-ready .pill{opacity:0}\n.pill-title.is-dropped .pill:first-child{animation:drop-a .95s cubic-bezier(.45,0,.9,.5) both}\n.pill-title.is-dropped .pill:last-child{animation:drop-b .95s cubic-bezier(.45,0,.9,.5) .18s both}\n@keyframes drop-a{\n  0%{opacity:0;transform:translateY(-190px) rotate(0deg)}\n  10%{opacity:1}\n  52%{transform:translateY(0) rotate(-2.5deg);animation-timing-function:cubic-bezier(.2,.6,.4,1)}\n  70%{transform:translateY(-22px) rotate(-1deg);animation-timing-function:cubic-bezier(.5,0,.9,.5)}\n  85%{transform:translateY(0) rotate(-2.5deg);animation-timing-function:cubic-bezier(.2,.6,.4,1)}\n  93%{transform:translateY(-7px) rotate(-2deg)}\n  100%{opacity:1;transform:translateY(0) rotate(-2.5deg)}\n}\n@keyframes drop-b{\n  0%{opacity:0;transform:translateY(-190px) rotate(0deg)}\n  10%{opacity:1}\n  52%{transform:translateY(0) rotate(1.5deg);animation-timing-function:cubic-bezier(.2,.6,.4,1)}\n  70%{transform:translateY(-20px) rotate(3deg);animation-timing-function:cubic-bezier(.5,0,.9,.5)}\n  85%{transform:translateY(0) rotate(1.5deg);animation-timing-function:cubic-bezier(.2,.6,.4,1)}\n  93%{transform:translateY(-6px) rotate(2deg)}\n  100%{opacity:1;transform:translateY(0) rotate(1.5deg)}\n}\n.chapter-text{font-size:var(--fs-body);font-weight:700;line-height:var(--lh-body)}\n.chapter--brand .chapter-side{background:var(--green-soft)}\n.chapter--marketing .chapter-side{background:var(--red-soft)}\n.chapter--product .chapter-side{background:var(--purple-soft)}\n.chapter--video .chapter-side{background:var(--orange-soft)}\n.deliverables{list-style:none;padding:0;display:flex;flex-wrap:wrap;gap:8px}\n.deliverables li{padding:5px 16px 7px;border:var(--line);border-radius:999px;background:var(--white);font-size:var(--fs-ui);line-height:var(--lh-ui);font-weight:700}\n.chapter-media{padding:var(--media-pad);display:grid;grid-template-columns:minmax(0,1fr);gap:clamp(28px,3vw,48px);--stack-gap:clamp(28px,3vw,48px);align-content:start;min-width:0}\n.bleed{margin-inline:calc(-1 * var(--media-pad))}\n.bleed .rail-head{padding-inline:var(--media-pad)}\n.bleed .track{padding-inline:var(--media-pad);scroll-padding-inline:var(--media-pad)}\n\n/* website mockups */\n.site-row{align-items:flex-start}\n.device{border:var(--line);border-radius:var(--radius-m);overflow:hidden;background:var(--white);box-shadow:0 0 0 rgba(18,18,18,0);transition:border-color .45s ease,transform .35s ease,box-shadow .35s ease}\n.device:hover{border-color:var(--yellow);transform:translateY(-10px);box-shadow:0 24px 48px rgba(18,18,18,.25)}\n/* the levitation is reserved for the live site: a screenshot or recording stays still */\n.device:not(:has(iframe)):hover{border-color:var(--ink);transform:none;box-shadow:none}\n.device-bar{display:flex;align-items:center;gap:6px;height:34px;padding:0 14px;border-bottom:var(--line);background:var(--paper);font-size:var(--fs-small);line-height:var(--lh-small);font-weight:700}\n.device-bar i{width:10px;height:10px;border-radius:50%;border:var(--line);display:block}\n.device-bar span{margin-left:10px}\n.screen{position:relative;overflow:hidden;width:100%;aspect-ratio:var(--sr);max-height:calc(var(--max-h) - 34px)}\n.screen iframe{position:absolute;top:0;left:0;border:0;max-width:none;transform-origin:0 0}\n.device--phone .device-bar{justify-content:center}\n.device--phone .device-bar span{margin-left:6px}\n.site-link{justify-self:start}\n\n/* result */\n.result{background:var(--ink);color:var(--white);border-color:var(--ink)}\n.result-text{font-size:var(--fs-h3);font-weight:800;line-height:var(--lh-h3)}\n.stats{margin-top:clamp(36px,5vw,80px);display:grid;grid-template-columns:repeat(3,1fr);gap:var(--gutter);list-style:none;padding:0}\n.stats li{border-top:2px solid #555;padding-top:14px}\n.stats b{display:block;font-size:var(--fs-h2);font-weight:900;line-height:var(--lh-h2);color:var(--yellow)}\n.stats span{display:block;margin-top:10px;max-width:16em}\n.result-quote{margin-top:clamp(36px,5vw,80px);align-items:stretch}\n.result-quote blockquote{flex:1.1 1 0;min-width:0;background:var(--yellow);color:var(--ink);border-radius:var(--radius-m);padding:clamp(24px,3vw,44px);display:flex;flex-direction:column;justify-content:space-between;gap:24px}\n.result-quote blockquote p{font-size:var(--fs-h3);font-weight:800;line-height:var(--lh-h3)}\n.result-quote blockquote.is-in cite{opacity:1;transition-delay:calc(var(--lines,1) * var(--line-step,.09s) + .35s)}\n.result-showcase{margin-top:var(--gutter)}\n.btn{display:inline-flex;align-items:center;gap:10px;padding:10px 26px 13px;border-radius:999px;border:var(--line);background:var(--yellow);color:var(--ink);font-weight:800;font-size:var(--fs-ui);line-height:var(--lh-ui);text-decoration:none}\n.btn:hover{background:var(--white)}\n\n/* related */\n.related{background:var(--white)}\n.related .inner{--media-pad:var(--pad)}\n.related .rail-head h2{font-size:var(--fs-h2);line-height:var(--lh-h2)}\n.related .rail-head{justify-content:flex-start;gap:24px;margin-bottom:clamp(24px,3vw,48px)}\n.related .rail-head h2{text-align:left}\n.related .track .proj{width:clamp(280px,30vw,460px)}\n.related .track .frame{height:auto;width:100%}\n.proj{position:relative;display:grid;gap:14px;align-content:start}\n.proj .frame{border:var(--line)}\n.proj h3{font-size:var(--fs-lead);line-height:var(--lh-lead)}\n.proj p{max-width:20em}\n.proj a.cover{position:absolute;inset:0;border-radius:var(--radius-m)}\n.proj .pills{position:relative;z-index:1}\n.proj .pill{padding:4px 16px 6px}\n\n@media (min-width:1025px){\n  .related .bleed{margin-inline:0}\n  .related .track{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));overflow:visible;padding-inline:0;cursor:auto}\n  .related .track .proj{width:auto}\n  .related .rail-btns{display:none}\n}\n.proj .frame{transition:border-color .45s ease}\n.proj:hover .frame{border-color:var(--yellow)}\n\n/* cta */\n.cta{background:var(--yellow);text-align:left}\n.cta .inner{min-height:clamp(252px,37vh,456px);display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;gap:clamp(48px,8vw,120px)}\n.cta h2{font-size:var(--fs-display);line-height:var(--lh-display);max-width:10em}\n.cta .btn{background:var(--ink);color:var(--white);font-size:var(--fs-lead);line-height:var(--lh-lead);padding:18px 44px 22px}\n.cta .btn:hover{background:var(--blue);color:var(--ink)}\n\n@media (min-width:1025px){\n  .related .bleed .rail-head{padding-inline:0}\n}\n\n/* tablet */\n@media (min-width:641px) and (max-width:1024px){\n  .stats span{max-width:none}\n}\n@media (max-width:1024px){\n  .hero-top,.sec-head,.handoff{grid-template-columns:1fr}\n  .to-result{min-height:220px}\n  .chapter{grid-template-columns:1fr}\n  .chapter-side{border-right:0;border-bottom:var(--line)}\n  .stats{grid-template-columns:1fr}\n}\n/* mobile */\n@media (max-width:640px){\n  :root{--radius-l:26px;--radius-m:14px;--media-pad:10px;--rail-h:420px}\n  .full-sm{flex-basis:100% !important}\n  .hide-sm{display:none !important}\n  .rail-btns{display:none}\n  .result-quote{flex-direction:column}\n  .result-quote blockquote{flex:none}\n  .related .track .proj{width:82vw}\n}\n@media (prefers-reduced-motion:reduce){\n  html{scroll-behavior:auto}\n  .to-result,.pill,.device,.proj .frame{transition:none}\n  .hero-media,.device:hover{animation:none}\n  .client-row .pill{animation:none;opacity:1}\n  .device,.device:hover{transition:none;transform:none}\n  .line>span,.quote cite,.result-quote cite{transform:none;opacity:1;transition:none}\n  .to-result:hover{transform:none}\n}\n</style>\n</head>\n<body>\n\n<main class=\"page\">\n\n  <!-- HERO \u2014 client name, tagline, industry, year, services, pillar pills, cover media (16:9, cropped) -->\n  <header class=\"card hero\">\n    <div class=\"inner\">\n      <div class=\"hero-top\">\n        <div class=\"hero-title\">\n          <p class=\"client-name\">Steam Coffee Shop</p>\n          <h1>Refreshing a pioneer brand for its community.</h1>\n        </div>\n        <div class=\"hero-info\">\n          <div class=\"client-row\">\n            <ul class=\"pills\" aria-label=\"Jump to a pillar\">\n              <li><a class=\"pill pill--brand\" href=\"#branding-design\">Branding &amp; Design</a></li>\n              <li><a class=\"pill pill--marketing\" href=\"#growth-content\">Growth &amp; Content</a></li>\n              <li><a class=\"pill pill--product\" href=\"#product-design\">Product Design</a></li>\n            </ul>\n          </div>\n          <ul class=\"info\">\n            <li>Coffee shop, HoReCa</li>\n            <li>2024 \u2013 2025</li>\n            <li>Brand strategy, brand facelift, content strategy, photo, video, social media, ad campaigns, merch, packaging, e-commerce website</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"hero-media\">\n        <figure style=\"--r:1.778\" data-fixed-ratio>\n          <div class=\"frame\"><video src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-cover.webm\" poster=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-001.jpg\" autoplay muted loop playsinline aria-label=\"Guests at a Steam table, sunlight through the window\"></video></div>\n        </figure>\n      </div>\n    </div>\n  </header>\n\n  <!-- PROBLEM \u2014 section title, 2-3 paragraphs with <strong> accents, context images, caption, client quote.\n       Ends with the blue solution intro and the black card that jumps to the result. -->\n  <section class=\"card problem\" id=\"problem\">\n    <div class=\"inner\">\n      <div class=\"sec-head\">\n        <h2>A pioneer that started to blend in</h2>\n        <div class=\"prose\">\n          <p>Steam opened when specialty coffee in Bucharest was <strong>still a niche</strong>. A decade later the city had <strong>over a hundred third-wave shops</strong>, many borrowing the same minimal look Steam helped popularise.</p>\n          <p>The identity <strong>felt dated</strong> next to the newcomers, the social channels <strong>had gone quiet</strong>, and the brand's biggest asset, the people who gather there every day, was <strong>invisible online</strong>.</p>\n          <p>Craft Coffee, the equipment business run by the same team, sold professional machines <strong>through phone calls and visits alone</strong>, with <strong>no shop of its own online</strong>.</p>\n        </div>\n      </div>\n\n      <div class=\"problem-media stack\">\n        <div class=\"row\">\n          <figure class=\"full-sm\" style=\"--r:1.596\">\n            <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-001.jpg\" alt=\"A full Steam interior with guests at every table\" loading=\"lazy\"></div>\n          </figure>\n          <figure style=\"--r:.528\">\n            <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-28.jpg\" alt=\"Barista preparing coffee behind the bar\" loading=\"lazy\"></div>\n          </figure>\n          <figure style=\"--r:.528\">\n            <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-26.jpg\" alt=\"A guest with her dog at Steam\" loading=\"lazy\"></div>\n          </figure>\n        </div>\n        <figcaption>A full house on a weekday morning, with the team and the regulars who make it feel like home.</figcaption>\n      </div>\n\n      <div class=\"quote\">\n        <blockquote>\n          <p data-lines>\u201cOur guests love this place. We needed a clear way to say what Steam stands for.\u201d</p>\n          <cite>Founder, Steam Coffee Shop</cite>\n        </blockquote>\n      </div>\n\n      <div class=\"handoff\">\n        <div class=\"solution-intro\" id=\"solution\">\n          <h2>Community, coffee and connection</h2>\n          <p>We started by listening. Surveys and interviews with guests pointed to what they value most about Steam: the feeling of belonging. That idea shaped the brand, the content, the merch and the website that follow.</p>\n        </div>\n        <a class=\"to-result\" href=\"#result\">\n          <b>+184%</b>\n          <span>Instagram engagement in six months, one of several results we delivered</span>\n          <span class=\"to-result-go\">Drop for more <span class=\"go-icon\" aria-hidden=\"true\">\u2193</span></span>\n        </a>\n      </div>\n    </div>\n  </section>\n\n  <!-- CHAPTER \u2014 one per pillar the project actually has. Duplicate or delete whole <section> blocks.\n       chapter--brand / chapter--marketing / chapter--product / chapter--video -->\n  <section class=\"card chapter chapter--brand\" id=\"branding-design\" aria-label=\"Branding and Design\">\n    <div class=\"chapter-side\">\n      <div>\n        <span class=\"pill-title\"><span class=\"pill pill--brand\">Branding</span><span class=\"pill pill--accent\">&amp; Design</span></span>\n        <p class=\"chapter-text\">The steaming cup guests recognise stays at the centre, now surrounded by a bolder typographic voice, a palette pulled from the shop itself and a positioning line the team can say out loud.</p>\n        <ul class=\"deliverables\">\n          <li>Customer research</li>\n          <li>Brand strategy</li>\n          <li>Brand positioning</li>\n          <li>Logo refinement</li>\n          <li>Logo lockups</li>\n          <li>Typography system</li>\n          <li>Colour system</li>\n          <li>Brand values</li>\n          <li>Tone of voice</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"chapter-media\">\n      <figure style=\"--r:2.463\">\n        <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-25-1.jpg\" alt=\"Steam logo lockups: stacked, horizontal and symbol-only\" loading=\"lazy\"></div>\n        <figcaption>Logo lockups for every surface, from cups to storefront</figcaption>\n      </figure>\n      <div class=\"row\">\n        <figure class=\"full-sm\" style=\"--r:1.779\">\n          <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-23.jpg\" alt=\"Colour palette: black, blue, green and grey\" loading=\"lazy\"></div>\n          <figcaption>Black, blue and green, with grey as the quiet base</figcaption>\n        </figure>\n        <figure class=\"full-sm\" style=\"--r:1.777\">\n          <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-24.jpg\" alt=\"Type specimen of the N27 typeface in regular, italic and bold\" loading=\"lazy\"></div>\n          <figcaption>N27 as the single brand typeface</figcaption>\n        </figure>\n      </div>\n      <figure style=\"--r:1.777\">\n        <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-10.jpg\" alt=\"Green brand board reading Community, coffee and connection\" loading=\"lazy\"></div>\n        <figcaption>The brand idea in one line</figcaption>\n      </figure>\n      <figure style=\"--r:1.777\">\n        <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-11.jpg\" alt=\"Blue brand board listing the brand values\" loading=\"lazy\"></div>\n        <figcaption>Five values that guide how the team treats every guest</figcaption>\n      </figure>\n    </div>\n  </section>\n\n  <!-- CHAPTER: MARKETING -->\n  <section class=\"card chapter chapter--marketing\" id=\"growth-content\" aria-label=\"Growth and Content\">\n    <div class=\"chapter-side\">\n      <div>\n        <span class=\"pill-title\"><span class=\"pill pill--marketing\">Growth</span><span class=\"pill pill--accent\">&amp; Content</span></span>\n        <p class=\"chapter-text\">The content follows the people. We shot the shop across a full season and built a posting rhythm around real guests, the team and the neighbourhood.</p>\n        <ul class=\"deliverables\">\n          <li>Content strategy</li>\n          <li>Photo production</li>\n          <li>Video production</li>\n          <li>Social media management</li>\n          <li>Instagram stories</li>\n          <li>Posters</li>\n          <li>Ad campaigns</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"chapter-media\">\n      <div class=\"stack\">\n        <div class=\"row\">\n          <figure style=\"--r:.5625\">\n            <div class=\"frame\"><video src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-reel.webm\" autoplay muted loop playsinline preload=\"metadata\" aria-label=\"Social media reel filmed inside Steam\"></video></div>\n          </figure>\n          <figure style=\"--r:1.1\">\n            <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/steam-aa.jpg\" alt=\"Friends around a table inside Steam\" loading=\"lazy\"></div>\n          </figure>\n        </div>\n        <figcaption>Season reel and the moments it was built from</figcaption>\n      </div>\n\n      <div class=\"rail bleed\" data-rail>\n        <div class=\"rail-head\">\n          <h4><span class=\"pill\" style=\"--rot:-7deg\">Instagram</span><span class=\"pill\" style=\"--rot:9deg\">stories</span></h4>\n          <div class=\"rail-btns\"><button type=\"button\" data-prev aria-label=\"Previous stories\">\u2190</button><button type=\"button\" data-next aria-label=\"Next stories\">\u2192</button></div>\n        </div>\n        <div class=\"track\" tabindex=\"0\" aria-label=\"Instagram stories, scroll horizontally\">\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-11-1.jpg\" alt=\"Green illustrated story with the community brand line\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-7-1.jpg\" alt=\"Story with two friends laughing and the brand line\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-4-1.jpg\" alt=\"Happyness story with two guests\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-5-1.jpg\" alt=\"New drink announcement story with latte art\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-8-1.jpg\" alt=\"Trust your local dealer illustrated story\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-10-1.jpg\" alt=\"Blue illustrated story: Let's coffee some more\" loading=\"lazy\"></div></figure>\n        </div>\n      </div>\n\n      <div class=\"rail bleed\" data-rail>\n        <div class=\"rail-head\">\n          <h4><span class=\"pill\" style=\"--rot:-10deg\">In-store</span><span class=\"pill\" style=\"--rot:4deg\">posters</span></h4>\n          <div class=\"rail-btns\"><button type=\"button\" data-prev aria-label=\"Previous posters\">\u2190</button><button type=\"button\" data-next aria-label=\"Next posters\">\u2192</button></div>\n        </div>\n        <div class=\"track\" style=\"gap:10px\" tabindex=\"0\" aria-label=\"In-store posters, scroll horizontally\">\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-12.jpg\" alt=\"Poster: Community, coffee and connection\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-13.jpg\" alt=\"Poster: Trust your local dealer\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.288\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-2-1.jpg\" alt=\"Tall vertical banner with the brand line\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-14.jpg\" alt=\"Poster with opening hours\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.552\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-15.jpg\" alt=\"Poster: Happyness is part of our daily coffee routine\" loading=\"lazy\"></div></figure>\n        </div>\n      </div>\n\n      <div class=\"stack\">\n        <div class=\"rail-head\"><h4><span class=\"pill\" style=\"--rot:-6deg\">Photography</span></h4></div>\n        <figure style=\"--r:2.426\">\n          <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-4.jpg\" alt=\"Guests seen through the shop window\" loading=\"lazy\"></div>\n        </figure>\n        <div class=\"row\">\n          <figure style=\"--r:1.027\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-8.jpg\" alt=\"A guest holding a cup at the counter\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:1.173\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-1.jpg\" alt=\"Busy interior of Steam\" loading=\"lazy\"></div></figure>\n        </div>\n        <div class=\"row\">\n          <figure style=\"--r:1.38\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-1-1.jpg\" alt=\"Barista working at the Steam bar\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:.528\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-27.jpg\" alt=\"Two guests talking over coffee\" loading=\"lazy\"></div></figure>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- CHAPTER: PRODUCT -->\n  <section class=\"card chapter chapter--product\" id=\"product-design\" aria-label=\"Product Design\">\n    <div class=\"chapter-side\">\n      <div>\n        <span class=\"pill-title\"><span class=\"pill pill--product\">Product</span><span class=\"pill pill--accent\">Design</span></span>\n        <p class=\"chapter-text\">An online shop that puts the Craft Coffee catalogue in front of buyers, and a family of illustrated characters that turned the brand line into T-shirts, cups and a limited 10th anniversary cup.</p>\n        <ul class=\"deliverables\">\n          <li>E-commerce website</li>\n          <li>Illustration system</li>\n          <li>T-shirt collection</li>\n          <li>Cup design</li>\n          <li>Packaging design</li>\n          <li>10-year anniversary cup</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"chapter-media\">\n      <div class=\"stack\">\n        <div class=\"rail-head\"><h4><span class=\"pill\" style=\"--rot:-9deg\">Online</span><span class=\"pill\" style=\"--rot:7deg\">shop</span></h4></div>\n        <div class=\"row site-row\">\n          <figure class=\"hide-sm\" style=\"--r:1.6\">\n            <div class=\"device\">\n              <div class=\"device-bar\" aria-hidden=\"true\"><i></i><i></i><i></i><span>craftcoffee.ro</span></div>\n              <div class=\"screen\" style=\"--sr:1.6\" data-screen=\"1440\"><iframe src=\"https://craftcoffee.ro/branduri/\" width=\"1440\" height=\"900\" loading=\"lazy\" title=\"craftcoffee.ro, desktop view\"></iframe></div>\n            </div>\n          </figure>\n          <figure class=\"full-sm\" style=\"--r:.462\">\n            <div class=\"device device--phone\">\n              <div class=\"device-bar\" aria-hidden=\"true\"><i></i><span>craftcoffee.ro</span></div>\n              <div class=\"screen\" style=\"--sr:.462\" data-screen=\"390\"><iframe src=\"https://craftcoffee.ro/branduri/\" width=\"390\" height=\"844\" loading=\"lazy\" title=\"craftcoffee.ro, mobile view\"></iframe></div>\n            </div>\n          </figure>\n        </div>\n        <figcaption>craftcoffee.ro, a shop for professional espresso machines, grinders and brew equipment.</figcaption>\n        <a class=\"btn site-link\" href=\"https://craftcoffee.ro/\" target=\"_blank\" rel=\"noopener\">Visit craftcoffee.ro <span aria-hidden=\"true\">\u2197</span></a>\n      </div>\n\n      <div class=\"stack\">\n        <div class=\"rail-head\"><h4><span class=\"pill\" style=\"--rot:-5deg\">T-shirt</span><span class=\"pill\" style=\"--rot:11deg\">collection</span></h4></div>\n        <div class=\"row\">\n          <figure style=\"--r:1.203\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Tricouri-Steam-Cromaticstudios-4.jpg\" alt=\"White T-shirts with an illustrated character\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:1.203\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Tricouri-Steam-Cromaticstudios-3.jpg\" alt=\"White T-shirts with illustrated guests at a table\" loading=\"lazy\"></div></figure>\n        </div>\n        <div class=\"row\">\n          <figure style=\"--r:1.203\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Tricouri-Steam-Cromaticstudios-2.jpg\" alt=\"White T-shirts with a cyclist illustration\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:1.203\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Tricouri-Steam-Cromaticstudios-1.jpg\" alt=\"White T-shirts with a group illustration\" loading=\"lazy\"></div></figure>\n        </div>\n        <figcaption>The T-shirt collection, one character per design</figcaption>\n      </div>\n\n      <figure style=\"--r:1.983\">\n        <div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-2.jpg\" alt=\"Two people in green Steam T-shirts sitting outside\" loading=\"lazy\"></div>\n        <figcaption>Worn by the community around the shop</figcaption>\n      </figure>\n\n      <div class=\"stack\">\n        <div class=\"rail-head\"><h4><span class=\"pill\" style=\"--rot:-12deg\">Prints</span><span class=\"pill\" style=\"--rot:6deg\">packaging</span></h4></div>\n        <div class=\"row\">\n          <figure style=\"--r:1.027\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-3.jpg\" alt=\"Back print of a white Steam T-shirt\" loading=\"lazy\"></div></figure>\n          <figure style=\"--r:1.173\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios.jpg\" alt=\"Steam takeaway cups on a sunny table\" loading=\"lazy\"></div></figure>\n        </div>\n        <figcaption>Back print and takeaway cups</figcaption>\n      </div>\n    </div>\n  </section>\n\n  <!-- RESULT \u2014 statement, 1-3 stats (drop the <li> you do not have), client quote, final showcase -->\n  <section class=\"card result\" id=\"result\">\n    <div class=\"inner\">\n      <p class=\"result-text\">Within six months Steam's channels turned into a steady conversation with its guests, with all of the growth coming from organic content. Regulars wear the merch around the city, and Craft Coffee takes orders for professional equipment through a shop of its own.</p>\n\n      <ul class=\"stats\">\n        <li><b>+184%</b><span>Instagram engagement rate in the first six months</span></li>\n        <li><b>3\u00d7</b><span>more guests tagging Steam in their own posts</span></li>\n        <li><b>0 dinero</b><span>paid engagement budget</span></li>\n      </ul>\n\n      <div class=\"row result-quote\">\n        <blockquote>\n          <p data-lines>\u201cGuests now come in wearing our T-shirts. It's the clearest sign the brand works.\u201d</p>\n          <cite>Founder, Steam Coffee Shop</cite>\n        </blockquote>\n        <figure style=\"--r:1.027\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Steam-Cromaticstudios-5.jpg\" alt=\"A guest seen from behind wearing a green Steam T-shirt\" loading=\"lazy\"></div></figure>\n      </div>\n\n      <div class=\"stack result-showcase\">\n        <figure style=\"--r:1.754\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-003.jpg\" alt=\"A crowd outside Steam on a sunny day\" loading=\"lazy\"></div></figure>\n        <figure style=\"--r:1.566\"><div class=\"frame\"><img src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Steam-Cromaticstudios-002.jpg\" alt=\"Guests in green Steam T-shirts drinking coffee outside\" loading=\"lazy\"></div></figure>\n      </div>\n\n    </div>\n  </section>\n\n  <!-- RELATED \u2014 three projects: cover media, name, tagline, pillar pills -->\n  <section class=\"card related\" aria-labelledby=\"related-title\">\n    <div class=\"inner\">\n      <div class=\"rail bleed\" data-rail>\n        <div class=\"rail-head\">\n          <h2 id=\"related-title\">Related projects</h2>\n          <div class=\"rail-btns\"><button type=\"button\" data-prev aria-label=\"Previous projects\">\u2190</button><button type=\"button\" data-next aria-label=\"Next projects\">\u2192</button></div>\n        </div>\n        <div class=\"track\" tabindex=\"0\" aria-label=\"Related projects, scroll horizontally\">\n          <article class=\"proj\">\n            <figure style=\"--r:1.778\" data-fixed-ratio><div class=\"frame\"><video src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/elithia-homepage.webm\" autoplay muted loop playsinline preload=\"metadata\" aria-hidden=\"true\"></video></div></figure>\n            <h3>Elithia</h3>\n            <p>Making motherhood a soothing, joyful experience.</p>\n            <ul class=\"pills\"><li><span class=\"pill pill--product\">Product Design</span></li><li><span class=\"pill pill--brand\">Branding &amp; Design</span></li><li><span class=\"pill pill--marketing\">Growth &amp; Content</span></li></ul>\n            <a class=\"cover\" href=\"https://cromaticstudios.com/proiecte/elithia/\" aria-label=\"Elithia case study\"></a>\n          </article>\n          <article class=\"proj\">\n            <figure style=\"--r:1.778\" data-fixed-ratio><div class=\"frame\"><video src=\"https://cromaticstudios.com/wp-content/uploads/2025/06/Help4brain.webm\" autoplay muted loop playsinline preload=\"metadata\" aria-hidden=\"true\"></video></div></figure>\n            <h3>Help4Brain</h3>\n            <p>Enabling a pharma challenger to become a leader.</p>\n            <ul class=\"pills\"><li><span class=\"pill pill--product\">Product Design</span></li><li><span class=\"pill pill--marketing\">Growth &amp; Content</span></li></ul>\n            <a class=\"cover\" href=\"https://cromaticstudios.com/proiecte/help4brain/\" aria-label=\"Help4Brain case study\"></a>\n          </article>\n          <article class=\"proj\">\n            <figure style=\"--r:1.778\" data-fixed-ratio><div class=\"frame\"><video src=\"https://cromaticstudios.com/wp-content/uploads/2025/07/Routin-Cover.webm\" autoplay muted loop playsinline preload=\"metadata\" aria-hidden=\"true\"></video></div></figure>\n            <h3>Routine Paris</h3>\n            <p>Making in Romania a brand that can win in Paris.</p>\n            <ul class=\"pills\"><li><span class=\"pill pill--product\">Product Design</span></li><li><span class=\"pill pill--marketing\">Growth &amp; Content</span></li></ul>\n            <a class=\"cover\" href=\"https://cromaticstudios.com/proiecte/routine-paris/\" aria-label=\"Routine Paris case study\"></a>\n          </article>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- CTA \u2014 same wording on every project -->\n  <section class=\"card cta\">\n    <div class=\"inner\">\n      <h2>What is your winning soundtrack?</h2>\n      <a class=\"btn\" href=\"https://cromaticstudios.com/contact/\">We can bring the mixtape</a>\n    </div>\n  </section>\n\n</main>\n\n<script>\n// carousels: prev/next buttons\ndocument.querySelectorAll('[data-rail]').forEach(rail=>{\n  const track=rail.querySelector('.track');\n  const prev=rail.querySelector('[data-prev]');\n  const next=rail.querySelector('[data-next]');\n  if(!track||!prev||!next) return;\n  const step=()=>{const item=track.firstElementChild;const gap=parseFloat(getComputedStyle(track).columnGap)||0;return item?item.getBoundingClientRect().width+gap:track.clientWidth};\n  const update=()=>{\n    const max=track.scrollWidth-track.clientWidth-2;\n    prev.disabled=track.scrollLeft<=2;\n    next.disabled=track.scrollLeft>=max;\n    rail.querySelector('.rail-btns').style.visibility=max<=0?'hidden':'visible';\n  };\n  let down=false,startX=0,startLeft=0,moved=false,target=0,raf=0;\n  const follow=()=>{raf=0;track.scrollLeft=target;};\n  track.addEventListener('pointerdown',e=>{\n    if(e.pointerType!=='mouse'||e.button!==0||track.scrollWidth<=track.clientWidth+2)return;\n    down=true;moved=false;startX=e.clientX;startLeft=track.scrollLeft;target=startLeft;\n    track.classList.add('is-dragging');\n    track.setPointerCapture(e.pointerId);\n  });\n  track.addEventListener('pointermove',e=>{\n    if(!down)return;\n    e.preventDefault();\n    const dx=e.clientX-startX;\n    if(Math.abs(dx)>3)moved=true;\n    target=startLeft-dx;\n    if(!raf)raf=requestAnimationFrame(follow);\n  });\n  const endDrag=e=>{\n    if(!down)return;\n    down=false;\n    if(raf){cancelAnimationFrame(raf);raf=0;track.scrollLeft=target;}\n    try{track.releasePointerCapture(e.pointerId)}catch(err){}\n    const x=track.scrollLeft;\n    track.classList.remove('is-dragging');\n    track.scrollLeft=x;\n  };\n  track.addEventListener('pointerup',endDrag);\n  track.addEventListener('pointercancel',endDrag);\n  track.addEventListener('dragstart',e=>e.preventDefault());\n  track.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);\n  prev.addEventListener('click',()=>track.scrollBy({left:-step(),behavior:'smooth'}));\n  next.addEventListener('click',()=>track.scrollBy({left:step(),behavior:'smooth'}));\n  track.addEventListener('scroll',update,{passive:true});\n  addEventListener('resize',update);\n  addEventListener('load',update);\n  update();\n});\n\n// videos: use the file's real ratio (no cropping), play only when visible, respect reduced motion\nconst reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst vids=document.querySelectorAll('video');\nvids.forEach(v=>{\n  const fit=()=>{if(v.videoWidth&&v.videoHeight){const fig=v.closest('figure');if(fig&&!fig.hasAttribute('data-fixed-ratio'))fig.style.setProperty('--r',(v.videoWidth/v.videoHeight).toFixed(4));}};\n  if(v.readyState>=1)fit();else v.addEventListener('loadedmetadata',fit,{once:true});\n});\nif(reduce){\n  vids.forEach(v=>{v.removeAttribute('autoplay');v.pause();v.controls=true;});\n}else if('IntersectionObserver' in window){\n  const io=new IntersectionObserver(entries=>entries.forEach(e=>{\n    if(e.isIntersecting){e.target.play().catch(()=>{});}else{e.target.pause();}\n  }),{threshold:.15});\n  vids.forEach(v=>io.observe(v));\n}\n\n// website mockups: scale the live site to the device width\nconst screens=document.querySelectorAll('[data-screen]');\nconst scale=s=>{\n  const f=s.querySelector('iframe');\n  const k=s.clientWidth/Number(s.dataset.screen);\n  if(!k) return;\n  f.style.width=s.dataset.screen+'px';\n  f.style.height=Math.ceil(s.clientHeight/k)+'px';\n  f.style.transform=`scale(${k})`;\n};\nif('ResizeObserver' in window){const ro=new ResizeObserver(es=>es.forEach(e=>scale(e.target)));screens.forEach(s=>ro.observe(s));}\nelse{screens.forEach(scale);addEventListener('resize',()=>screens.forEach(scale));}\n\n// pillar titles: the two pills drop in once, when the chapter first shows\nif(!matchMedia('(prefers-reduced-motion: reduce)').matches){\n  const titles=[...document.querySelectorAll('.chapter-side .pill-title')];\n  titles.forEach(t=>t.classList.add('drop-ready'));\n  const dropIo=new IntersectionObserver(es=>es.forEach(e=>{\n    if(e.isIntersecting){e.target.classList.add('is-dropped');dropIo.unobserve(e.target);}\n  }),{threshold:.6});\n  titles.forEach(t=>dropIo.observe(t));\n}\n\n// quote: reveal one line at a time\ndocument.querySelectorAll('[data-lines]').forEach(el=>{\n  const text=el.textContent.trim();\n  const build=()=>{\n    el.innerHTML=text.split(/\\s+/).map(w=>`<span class=\"w\">${w}</span>`).join(' ');\n    const words=[...el.querySelectorAll('.w')];\n    const lines=[];let top=null;\n    words.forEach(w=>{const t=Math.round(w.offsetTop);if(top===null||t!==top){lines.push([]);top=t;}lines[lines.length-1].push(w.textContent);});\n    el.innerHTML=lines.map((l,i)=>`<span class=\"line\" style=\"--i:${i}\"><span>${l.join(' ')}</span></span>`).join('');\n    const holder=el.closest('blockquote')||el;\n    holder.style.setProperty('--lines',lines.length);\n  };\n  build();\n  let t;addEventListener('resize',()=>{clearTimeout(t);t=setTimeout(()=>{(el.closest('blockquote')||el).classList.remove('is-in');build();io2.observe(el);},200);});\n});\nconst io2=new IntersectionObserver(es=>es.forEach(e=>{\n  if(e.isIntersecting){(e.target.closest('blockquote')||e.target).classList.add('is-in');io2.unobserve(e.target);}\n}),{threshold:.4});\ndocument.querySelectorAll('[data-lines]').forEach(el=>io2.observe(el));\n\n// mobile: sections that end with text get double bottom padding\nconst small=matchMedia('(max-width: 640px)');\nconst tablet=matchMedia('(min-width: 641px) and (max-width: 1024px)');\nconst TEXT=new Set(['P','FIGCAPTION','LI','CITE','BLOCKQUOTE','H1','H2','H3','H4','SPAN']);\nconst isHidden=el=>getComputedStyle(el).display==='none';\nconst lastVisible=el=>{let c=el.lastElementChild;while(c&&isHidden(c))c=c.previousElementSibling;return c;};\nconst endsWithText=box=>{\n  let el=lastVisible(box);\n  while(el&&lastVisible(el)&&!el.matches('.btn,.pill,.frame,.to-result,.solution-intro'))el=lastVisible(el);\n  return !!el&&TEXT.has(el.tagName)&&!el.closest('.btn,.pill,.frame,.to-result,.solution-intro');\n};\nconst pads=[...document.querySelectorAll('.card')].map(c=>c.lastElementChild).filter(Boolean);\nconst applyPad=()=>pads.forEach(b=>{\n  b.style.paddingBottom='';\n  if(!endsWithText(b))return;\n  const pb=parseFloat(getComputedStyle(b).paddingBottom);\n  if(small.matches)b.style.paddingBottom=(pb*2)+'px';\n  else if(tablet.matches)b.style.paddingBottom=(pb+45)+'px';\n});\nsmall.addEventListener('change',applyPad);\ntablet.addEventListener('change',applyPad);\naddEventListener('load',applyPad);\napplyPad();\n<\\/script>\n</body>\n</html>\n";
