      p.style.background = PILL_COLORS[(seed + n) % PILL_COLORS.length];
      p.style.setProperty("--rot", `${((seed + n) % 2 === 0 ? -1 : 1) * (1.6 + (seed + 3 * n) % 3)}deg`);
