        const b = el("button", "crew-face", `<span class="cf-ring" style="--cc:${col}">${src ? `<img src="${src}" alt="" loading="lazy">` : `<b>${n.replace(/[^A-Za-zĂÂÎȘȚăâîșț]/g, "").slice(0, 1)}</b>`}</span><span class="cf-tag" style="--cc:${col}">${n}</span>`);
