        scene.add(g);
        const noOutline = (m) => { m.userData.outlineParameters = { visible: false }; return m; };
        // fish: little bodies with tails, six colours, schools wheeling around you
        const FCOL = ["#ff8a3d", "#ffd23d", "#3dd6ff", "#ff5fa2", "#9dff6a", "#b58cff"];
        const bodyG = new SphereGeometry(1, 12, 8), tailG = new ConeGeometry(0.9, 1.6, 6), eyeG = new SphereGeometry(0.22, 6, 5);
        tailG.rotateX(Math.PI / 2);
        const eyeM = new MeshBasicMaterial({ color: "#0a0a0a" });
