        const bubbles = new InstancedMesh(new SphereGeometry(1, 8, 6), bubM, BN);
        bubbles.frustumCulled = false;
        const bub = [...Array(BN)].map(() => ({ x: (Math.random() - 0.5) * 1600, y: Math.random() * 420, z: (Math.random() - 0.5) * 1600, v: 18 + Math.random() * 38, s: 0.8 + Math.random() * 2.6, w: Math.random() * 6.28 }));
        g.add(bubbles);
        // kelp along the route: one instanced draw call, swaying in the vertex shader
        const kelpSpots = [];
        {
          propRoutes.walk(150, (L, p, tn) => {
            for (const side of [-1, 1]) {
              if (Math.random() < 0.35) continue;
              const off = 70 + Math.random() * 90;
              kelpSpots.push([p.x - tn.z * off * side + (Math.random() - 0.5) * 30, p.z + tn.x * off * side + (Math.random() - 0.5) * 30, 0.7 + Math.random() * 0.9]);
            }
          }, 200);
        }
        const kelpGeo = new CylinderGeometry(1.6, 3.2, 90, 5, 8);
        kelpGeo.translate(0, 45, 0);
