          const doorShape = new Shape();
          doorShape.moveTo(-9, 0); doorShape.lineTo(9, 0); doorShape.lineTo(9, 18); doorShape.absarc(0, 18, 9, 0, Math.PI, false); doorShape.lineTo(-9, 0);
          const door = new Mesh(new ExtrudeGeometry(doorShape, { depth: 3, bevelEnabled: false, curveSegments: 14 }), metal);
          door.position.set(0, 6, 32.6);
